# R7: Picklable functor classes for type conversions
class FloatConvert(object):
    """Convert string to float - picklable functor."""
    def __call__(self, s):
        return float(s)

class DecimalConvert(object):
    """Convert string to Decimal - picklable functor."""
    def __call__(self, s):
        return Decimal(s)

class PercentageConvert(object):
    """Convert percentage string to float - picklable functor."""
    def __call__(self, s):
        return float(s.rstrip('%')) / 100.0

class IntConvertFunctor(object):
    """Convert string to int with optional base - picklable functor."""
    def __init__(self, base=None):
        self.base = base

    def __call__(self, s):
        if self.base is not None:
            # Remove optional prefix and convert
            s_stripped = s.lstrip('0bBxXoO')
